macro_rules! mkbin_override {
    ($module:ident, { $($mod_name:ident => { $($override:tt)* }),* }) => {
        mkbin_override_inner!($module, $($mod_name => { $($override)* }),*);
    };
    ($module:ident, {}) => {};
}

macro_rules! mkbin_override_inner {
    ($module:ident, $module:ident => { $($override:tt)* }, $($rest:tt)*) => {
        $($override)*
    };
    ($module:ident, $other:ident => { $($override:tt)* }, $($rest:tt)*) => {
        mkbin_override_inner!($module, $($rest)*);
    };
    ($module:ident,) => {};
}
